import{_ as t,a,b as r,c as o,d as i}from"./chunks/08e-preview-csv.B3Xiiyyf.js";import{_ as s}from"./chunks/08f-preview-office.BOqnux27.js";import{_ as d,o as p,c as l,a0 as n}from"./chunks/framework.DfN8ZSCw.js";const P=JSON.parse('{"title":"Preview","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/preview.md","filePath":"en/features/preview.md","lastUpdated":null}'),c={name:"en/features/preview.md"};function h(f,e,u,m,w,b){return p(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h1><p>Click a file to preview it in the workspace without downloading to your laptop first. Desktop uses a multi-tab workspace; on phones preview swaps full-screen.</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><p>Zoom and pan; the toolbar adjusts scale.</p><p><img src="'+t+'" alt="Image preview plot.png"></p><h2 id="markdown-text" tabindex="-1">Markdown / text <a class="header-anchor" href="#markdown-text" aria-label="Permalink to &quot;Markdown / text&quot;">​</a></h2><p>Markdown is rendered; plain text and code use a syntax-highlighted editor (read-only: find, wrap).</p><p><img src="'+a+'" alt="Markdown preview"></p><p><img src="'+r+'" alt="Code preview hello.py"></p><h2 id="pdf" tabindex="-1">PDF <a class="header-anchor" href="#pdf" aria-label="Permalink to &quot;PDF&quot;">​</a></h2><p>Built-in PDF viewer with Adaptive / percentage zoom. The demo dataset’s <code>demo-report.pdf</code> is a multi-page synthetic lab report (tables, multi-panel figures, equations) so the preview looks realistically dense.</p><p><img src="'+o+'" alt="PDF preview"></p><h2 id="csv-tsv" tabindex="-1">CSV / TSV <a class="header-anchor" href="#csv-tsv" aria-label="Permalink to &quot;CSV / TSV&quot;">​</a></h2><p>Table rendering with row/column counts and delimiter; toggle Raw / Copy.</p><p><img src="'+i+'" alt="CSV preview"></p><h2 id="office-optional" tabindex="-1">Office (optional) <a class="header-anchor" href="#office-optional" aria-label="Permalink to &quot;Office (optional)&quot;">​</a></h2><p>Word / PowerPoint convert to PDF on the Agent via LibreOffice; spreadsheets export one CSV per sheet. Requires <code>FILEBOX_AGENT_SOFFICE</code> — see <a href="/filebox/docs/en/ops/office">Office preview</a>.</p><p><img src="'+s+'" alt="PowerPoint → PDF preview"></p><p>Settings has an <strong>Office preview</strong> toggle (browser-local preference, on by default).</p><h2 id="supported-types" tabindex="-1">Supported types <a class="header-anchor" href="#supported-types" aria-label="Permalink to &quot;Supported types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Behavior</th></tr></thead><tbody><tr><td>Images</td><td>Zoom / pan (including TIFF)</td></tr><tr><td>PDF</td><td>Built-in viewer</td></tr><tr><td>Markdown</td><td>Rendered</td></tr><tr><td>Code / text / logs</td><td>Monaco read-only</td></tr><tr><td>HTML</td><td>Sandboxed session</td></tr><tr><td>CSV / TSV</td><td>Table</td></tr><tr><td>Word / PPT</td><td>Optional: Agent-side → PDF</td></tr><tr><td>Excel / ODS</td><td>Optional: each sheet → CSV</td></tr></tbody></table><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Desktop multi-tab; close/switch; keyboard shortcuts supported.</li><li>Very large files ask before loading so the browser stays responsive.</li><li>Use <strong>Download</strong> from the preview bar.</li><li>Without <code>soffice</code>, Office files remain downloadable but preview is unavailable.</li></ul>',23)])])}const k=d(c,[["render",h]]);export{P as __pageData,k as default};
